<?php declare(strict_types=1);require_once __DIR__.'/includes/header.php';$posts=load_json('blog.json',[]);?><main><section class="page-hero"><div class="container"><div class="breadcrumb"><a href="<?= e(app_url('index.php')) ?>">Home</a><span>/</span><span>Journal</span></div><div class="eyebrow">2B2X Journal</div><h1>Notes on better browsing.</h1><p>Product thinking, interface craft, and practical ideas for building a more considered browser experience.</p></div></section><section class="section"><div class="container"><div class="section-heading"><div class="section-kicker">Latest stories</div><h2>Read the thinking.</h2></div><div class="blog-grid"><?php if(!$posts):?><div class="empty-state"><div class="empty-icon">✎</div><h3>No stories yet</h3><p>New articles will appear here.</p></div><?php else:foreach($posts as $index=>$post):?><article class="article-card reveal" data-reveal><div class="image"><div class="container" style="height:100%;display:grid;place-items:center"><span class="status-pill"><?= e((string)$post['category']) ?></span></div></div><div class="body"><div class="meta"><?= e(format_date((string)$post['date'])) ?> · <?= e((string)$post['author']) ?></div><h3><?= e((string)$post['title']) ?></h3><p><?= e(truncate((string)$post['excerpt'],160)) ?></p><a href="<?= e(app_url('blog-post.php?slug='.rawurlencode((string)$post['slug']))) ?>">Read story <span>↗</span></a></div></article><?php endforeach;endif; ?></div></div></section></main><?php require_once __DIR__.'/includes/footer.php'; ?>
